async function purchaseCosmeticWithCoins({ accountId, sku, cost }) {
  if (!accountId || !sku || !Number.isFinite(cost) || cost <= 0) {
    throw new Error('purchaseCosmeticWithCoins: accountId + sku + positive cost required');
  }
  const idx = sku.indexOf(':');
  if (idx < 1) throw new Error('Bad SKU shape (expected kind:value)');
  const kind = sku.slice(0, idx);
  const value = sku.slice(idx + 1);
  if (!value) throw new Error('Bad SKU shape (empty value)');
  const p = getPool();
  const client = await p.connect();
  try {
    await client.query('BEGIN');
    // Per-account advisory lock — serialises any concurrent buys (same or
    // different SKUs) so the FOR UPDATE balance lock + ownership claim +
    // ledger insert all see a consistent snapshot.
    await client.query(`SELECT pg_advisory_xact_lock($1::bigint)`, [accountId]);
    // Ensure profile row exists then lock the balance.
    await client.query(`INSERT INTO player_profiles (account_id) VALUES ($1) ON CONFLICT (account_id) DO NOTHING`, [accountId]);
    // Insert-first ownership claim: if the row already exists, ON CONFLICT
    // returns rowCount=0 and we bail BEFORE debiting — this closes the
    // double-spend race the architect flagged (two concurrent buys both
    // passing a pre-check then both debiting).
    const claim = await client.query(
      `INSERT INTO coin_owned_cosmetics (account_id, kind, value, coins_spent) VALUES ($1, $2, $3, $4)
       ON CONFLICT (account_id, kind, value) DO NOTHING RETURNING id`,
      [accountId, kind, value, cost]
    );
    if (claim.rowCount === 0) {
      await client.query('ROLLBACK');
      const err = new Error('Already owned'); err.code = 'ALREADY_OWNED'; throw err;
    }
    const br = await client.query(
      `SELECT COALESCE(coin_balance, 0)::int AS balance FROM player_profiles WHERE account_id = $1 FOR UPDATE`,
      [accountId]
    );
    const bal = br.rows[0]?.balance ?? 0;
    if (bal < cost) {
      await client.query('ROLLBACK'); // rolls back the ownership claim too — the user can retry once they earn enough.
      const err = new Error(`Insufficient coins (have ${bal}, need ${cost})`); err.code = 'INSUFFICIENT_FUNDS'; throw err;
    }
    await client.query(
      `INSERT INTO coin_transactions (account_id, delta, reason, ref_match_id) VALUES ($1, $2, $3, NULL)`,
      [accountId, -cost, `purchase:${sku}`.slice(0, 64)]
    );
    await client.query(
      `UPDATE player_profiles SET coin_balance = coin_balance - $1 WHERE account_id = $2`,
      [cost, accountId]
    );
    await client.query('COMMIT');
    return { ok: true, sku, kind, value, spent: cost, newBalance: bal - cost };
  } catch (e) {
    await client.query('ROLLBACK').catch(() => {});
    throw e;
  } finally {
    client.release();
  }
}

async function grantEntitlementWithCap({ accountId, sku, cap, grantedBy = null, metadata = null }) {
  if (!accountId || !sku) throw new Error('grantEntitlementWithCap: accountId + sku required');
  const p = getPool();
  const client = await p.connect();
  try {
    await client.query('BEGIN');
    // v6.63 / Task #207 — concurrency-safe cap enforcement.
    //
    // PostgreSQL uses snapshot isolation by default, so a naive
    // `SELECT COUNT(*) ... ; INSERT ...` pair inside a transaction is
    // STILL racy: two concurrent webhook fires can both observe
    // count=199 and both insert, blowing past the cap. The fix is a
    // per-SKU `pg_advisory_xact_lock` taken at the very top of the tx.
    // The lock is keyed on `hashtext(sku)` so each SKU gets its own
    // serialization point (no contention across SKUs), is held until
    // COMMIT/ROLLBACK, and is automatically released on connection
    // drop — so a crashed worker can never wedge the cap forever.
    await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [sku]);
    // Idempotent — if the user already owns it, succeed without touching cap.
    const ex = await client.query(
      `SELECT 1 FROM entitlements WHERE account_id = $1 AND sku = $2 LIMIT 1`,
      [accountId, sku]
    );
    if (ex.rows.length > 0) {
      await client.query('COMMIT');
      return { ok: true, granted: false, reason: 'already_owned' };
    }
    if (cap && cap > 0) {
      // The COUNT runs while we hold the per-SKU advisory lock, so
      // any concurrent grant for the same SKU is blocked here until
      // we COMMIT/ROLLBACK — the count + insert pair is now atomic
      // with respect to other grant_with_cap callers.
      const cnt = await client.query(
        `SELECT COUNT(*)::int AS n FROM entitlements WHERE sku = $1`,
        [sku]
      );
      if ((cnt.rows[0]?.n || 0) >= cap) {
        await client.query('ROLLBACK');
        return { ok: false, granted: false, reason: 'cap_reached' };
      }
    }
    await client.query(
      `INSERT INTO entitlements (account_id, sku, granted_by, metadata)
       VALUES ($1, $2, $3, COALESCE($4::jsonb, '{}'::jsonb))
       ON CONFLICT (account_id, sku) DO NOTHING`,
      [accountId, sku, grantedBy, metadata ? JSON.stringify(metadata) : null]
    );
    await client.query('COMMIT');
    return { ok: true, granted: true, reason: null };
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch (_) {}
    throw err;
  } finally {
    client.release();
  }
}

// Task #256 — persist a Founders Pass cap-race refund attempt. Idempotent on
// stripe_session_id so a Stripe webhook retry won't duplicate the audit row.
// `status` is one of 'refunded' (refund succeeded) or 'refund_failed' (Stripe
// rejected the refund — operator must intervene).
async function recordFoundersRingRefund({
  accountId,
  sku,
  stripeSessionId,
  stripePaymentIntent = null,
  stripeRefundId = null,
  amountCents = null,
  currency = null,
  status,
  errorMessage = null,
}) {
  if (!accountId || !sku || !stripeSessionId || !status) {
    throw new Error('recordFoundersRingRefund: accountId, sku, stripeSessionId, status required');
  }
  const p = getPool();
  const r = await p.query(
    `INSERT INTO founders_ring_refunds
       (account_id, sku, stripe_session_id, stripe_payment_intent, stripe_refund_id,
        amount_cents, currency, status, error_message)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
     ON CONFLICT (stripe_session_id) DO UPDATE SET
       stripe_refund_id = COALESCE(EXCLUDED.stripe_refund_id, founders_ring_refunds.stripe_refund_id),
       status = EXCLUDED.status,
       error_message = EXCLUDED.error_message
     RETURNING *`,
    [accountId, sku, stripeSessionId, stripePaymentIntent, stripeRefundId,
     amountCents, currency, status, errorMessage]
  );
  return r.rows[0] || null;
}

async function listFoundersRingRefunds({ limit = 200 } = {}) {
  const p = getPool();
  const r = await p.query(
    `SELECT * FROM founders_ring_refunds ORDER BY created_at DESC LIMIT $1`,
    [Math.min(Math.max(parseInt(limit, 10) || 200, 1), 1000)]
  );
  return r.rows;
}

