// ---------- Pro Tier (`pro_tier`) ----------
// Lifetime-unlock paid feature. One row per Stripe checkout. Active rows
// grant Pro membership; refunded rows revoke it. The route layer caches
// isProMember() results briefly so we don't hammer the DB on every gated
// request.
async function isProMember(accountId) {
  if (!accountId) return false;
  // Owner perk — superusers are always Pro (no row required).
  if (isSuperuserAccountId(accountId)) return true;
  const p = getPool();
  // Task #318 — monthly subscriptions grant Pro while active/past_due
  // (past_due is a Stripe-driven grace window for failed invoices).
  // Lifetime founders are always Pro.
  // Task #664 — comp rows (Pro-time lootbox drops) carry status='active' but
  // are time-bounded: they only grant Pro while current_period_end is in the
  // future. Every non-comp plan_type keeps its existing behaviour unchanged.
  const r = await p.query(
    `SELECT 1 FROM pro_subscriptions
      WHERE account_id = $1 AND status IN ('active','lifetime','past_due')
        AND (plan_type IS DISTINCT FROM 'comp'
             OR (current_period_end IS NOT NULL AND current_period_end > NOW()))
      LIMIT 1`,
    [accountId]
  );
  return r.rows.length > 0;
}

// Task #318 — true iff the player has ever held a lifetime (Founder) row.
async function isFounder(accountId) {
  if (!accountId) return false;
  // Owner perk — superusers hold every Founder-gated cosmetic (frame/ring/badge).
  if (isSuperuserAccountId(accountId)) return true;
  // Task #318 — Founder entitlement must require a *live* lifetime row, not
  // just the historical is_founder flag. Otherwise a refunded lifetime
  // purchase (status flips to 'refunded' via markProRefunded, but the
  // is_founder flag is preserved for audit) would keep granting access to
  // the Founder-only frame/badge indefinitely. Status must be 'lifetime'
  // (the active-grandfather state); refunded/cancelled rows are excluded.
  const p = getPool();
  const r = await p.query(
    `SELECT 1 FROM pro_subscriptions
      WHERE account_id = $1 AND is_founder = TRUE AND status = 'lifetime'
      LIMIT 1`,
    [accountId]
  );
  return r.rows.length > 0;
}

// Returns the most-relevant subscription row for the player. Founder/lifetime
// wins, then active monthly, then past_due, then pending. Used to render the
// settings/billing page so the player can see plan / renewal / payment state.
async function getProSubscription(accountId) {
  if (!accountId) return null;
  const p = getPool();
  const r = await p.query(
    `SELECT id, account_id, plan_type, status, stripe_session_id,
            stripe_payment_intent, stripe_customer_id, stripe_subscription_id,
            amount_cents, currency,
            purchased_at, refunded_at, current_period_end, cancel_at_period_end,
            cancelled_at, is_founder, dunning_attempts, last_payment_failed_at,
            created_at, updated_at
       FROM pro_subscriptions
      WHERE account_id = $1
      ORDER BY (status = 'lifetime') DESC,
               (status = 'active') DESC,
               (status = 'past_due') DESC,
               (status = 'pending') DESC,
               created_at DESC
      LIMIT 1`,
    [accountId]
  );
  return r.rows[0] || null;
}

// Insert a pending checkout row. Called from POST /api/pro/checkout.
async function createProCheckout({ accountId, stripeSessionId, planType = 'lifetime', amountCents = null, currency = 'aud' }) {
  if (!accountId) throw new Error('createProCheckout: accountId required');
  if (!stripeSessionId) throw new Error('createProCheckout: stripeSessionId required');
  const p = getPool();
  const r = await p.query(
    `INSERT INTO pro_subscriptions
       (account_id, plan_type, status, stripe_session_id, amount_cents, currency)
     VALUES ($1, $2, 'pending', $3, $4, $5)
     ON CONFLICT (stripe_session_id) DO UPDATE
       SET updated_at = NOW()
     RETURNING id, account_id, status, stripe_session_id`,
    [accountId, planType, stripeSessionId, amountCents, currency]
  );
  return r.rows[0];
}

// Confirm a pending checkout via webhook. Idempotent: if the row is already
// active/lifetime, this is a no-op. Stamps purchased_at + the payment_intent so we
// can match later charge.refunded events back to the right row. Task #318:
// lifetime purchases land directly as status='lifetime' + is_founder=true so
// they survive the Pro-membership query and unlock Founder cosmetics.
async function confirmProPurchase({ stripeSessionId, stripePaymentIntent = null, amountCents = null, currency = null }) {
  if (!stripeSessionId) throw new Error('confirmProPurchase: stripeSessionId required');
  const p = getPool();
  const r = await p.query(
    `UPDATE pro_subscriptions
        SET status = CASE WHEN plan_type = 'lifetime' THEN 'lifetime' ELSE 'active' END,
            is_founder = CASE WHEN plan_type = 'lifetime' THEN TRUE ELSE is_founder END,
            stripe_payment_intent = COALESCE($2, stripe_payment_intent),
            amount_cents = COALESCE($3, amount_cents),
            currency = COALESCE($4, currency),
            purchased_at = COALESCE(purchased_at, NOW()),
            updated_at = NOW()
      WHERE stripe_session_id = $1
      RETURNING id, account_id, status, plan_type, is_founder, purchased_at`,
    [stripeSessionId, stripePaymentIntent, amountCents, currency]
  );
  return r.rows[0] || null;
}

// Task #318 — link a pro_subscriptions row to its Stripe customer + subscription
// ids. Called from /pro/checkout (subscription mode) after Stripe creates the
// Checkout Session, so subsequent subscription.* webhooks can find the row.
async function attachStripeIdsToProRow({ stripeSessionId, stripeCustomerId, stripeSubscriptionId }) {
  if (!stripeSessionId) return null;
  const p = getPool();
  const r = await p.query(
    `UPDATE pro_subscriptions
        SET stripe_customer_id = COALESCE($2, stripe_customer_id),
            stripe_subscription_id = COALESCE($3, stripe_subscription_id),
            updated_at = NOW()
      WHERE stripe_session_id = $1
      RETURNING id, account_id`,
    [stripeSessionId, stripeCustomerId || null, stripeSubscriptionId || null]
  );
  return r.rows[0] || null;
}

// Task #318 — apply a Stripe subscription webhook event to the local row.
// Maps Stripe status -> our state model. Idempotent on stripe_subscription_id.
// Returns the affected row (account_id is needed for cache invalidation + DM).
async function applyStripeSubscriptionEvent({
  stripeSubscriptionId,
  stripeCustomerId = null,
  status,                  // raw Stripe status: active|trialing|past_due|unpaid|canceled|incomplete|...
  currentPeriodEnd = null, // epoch seconds
  cancelAtPeriodEnd = false,
  amountCents = null,
  currency = null,
}) {
  if (!stripeSubscriptionId) return null;
  const p = getPool();
  let mapped;
  switch (status) {
    case 'active':
    case 'trialing':           mapped = 'active'; break;
    case 'past_due':
    case 'unpaid':             mapped = 'past_due'; break;
    case 'canceled':
    case 'incomplete_expired': mapped = 'cancelled'; break;
    case 'incomplete':         mapped = 'pending'; break;
    default:                   mapped = 'active';
  }
  const cpe = currentPeriodEnd ? new Date(currentPeriodEnd * 1000) : null;
  const cancelledAt = mapped === 'cancelled' ? new Date() : null;
  const r = await p.query(
    `UPDATE pro_subscriptions
        SET status = $2,
            stripe_customer_id = COALESCE($3, stripe_customer_id),
            current_period_end = COALESCE($4, current_period_end),
            cancel_at_period_end = $5,
            cancelled_at = CASE WHEN $2 = 'cancelled' THEN COALESCE(cancelled_at, $6) ELSE cancelled_at END,
            amount_cents = COALESCE($7, amount_cents),
            currency = COALESCE($8, currency),
            purchased_at = COALESCE(purchased_at, NOW()),
            updated_at = NOW()
      WHERE stripe_subscription_id = $1
      RETURNING id, account_id, status, plan_type, current_period_end, cancel_at_period_end`,
    [stripeSubscriptionId, mapped, stripeCustomerId, cpe, !!cancelAtPeriodEnd, cancelledAt, amountCents, currency]
  );
  return r.rows[0] || null;
}

// Task #318 — invoice.payment_succeeded handler. Resets dunning counter and
// promotes any past_due row back to active.
async function recordProInvoicePaid({ stripeSubscriptionId, currentPeriodEnd = null, amountCents = null, currency = null }) {
  if (!stripeSubscriptionId) return null;
  const p = getPool();
  const cpe = currentPeriodEnd ? new Date(currentPeriodEnd * 1000) : null;
  const r = await p.query(
    `UPDATE pro_subscriptions
        SET status = CASE WHEN status IN ('past_due','pending') THEN 'active' ELSE status END,
            dunning_attempts = 0,
            last_payment_failed_at = NULL,
            current_period_end = COALESCE($2, current_period_end),
            amount_cents = COALESCE($3, amount_cents),
            currency = COALESCE($4, currency),
            updated_at = NOW()
      WHERE stripe_subscription_id = $1
      RETURNING id, account_id, status`,
    [stripeSubscriptionId, cpe, amountCents, currency]
  );
  return r.rows[0] || null;
}

// Task #318 — invoice.payment_failed handler. Marks the row past_due and
// increments the dunning attempt counter (Stripe retries on its own; we
// surface the counter in the UI so the user knows to update their card).
async function recordProInvoiceFailed({ stripeSubscriptionId }) {
  if (!stripeSubscriptionId) return null;
  const p = getPool();
  const r = await p.query(
    `UPDATE pro_subscriptions
        SET status = CASE WHEN status = 'cancelled' THEN status ELSE 'past_due' END,
            dunning_attempts = dunning_attempts + 1,
            last_payment_failed_at = NOW(),
            updated_at = NOW()
      WHERE stripe_subscription_id = $1
      RETURNING id, account_id, status, dunning_attempts`,
    [stripeSubscriptionId]
  );
  return r.rows[0] || null;
}

// Task #318 — record the user's cancellation reason from the winback survey.
async function recordCancellationReason({ accountId, subscriptionId = null, reason, comment = null, winbackOffered = false, winbackAccepted = false }) {
  if (!accountId || !reason) throw new Error('recordCancellationReason: accountId + reason required');
  const p = getPool();
  const r = await p.query(
    `INSERT INTO pro_cancellation_reasons (account_id, subscription_id, reason, comment, winback_offered, winback_accepted)
     VALUES ($1, $2, $3, $4, $5, $6)
     RETURNING id`,
    [accountId, subscriptionId, reason, comment, winbackOffered, winbackAccepted]
  );
  return r.rows[0];
}

// Task #318 — admin report.
async function listCancellationReasons({ limit = 200 } = {}) {
  const p = getPool();
  const r = await p.query(
    `SELECT pcr.id, pcr.account_id, pcr.subscription_id, pcr.reason, pcr.comment,
            pcr.winback_offered, pcr.winback_accepted, pcr.created_at,
            COALESCE(rp.display_name, pcr.account_id::text) AS display_name
       FROM pro_cancellation_reasons pcr
       LEFT JOIN registered_players rp ON rp.account_id = pcr.account_id
      ORDER BY pcr.created_at DESC
      LIMIT $1`,
    [limit]
  );
  return r.rows;
}

// Task #318 — lapsed-subscriber list for the winback DM cron. Returns rows
// cancelled in the [olderThanDays - 1, olderThanDays] day window that haven't
// already received a DM at this stage (founders/lifetime excluded).
async function listLapsedSubscribersForDm({ stage, daysAgo }) {
  const p = getPool();
  const r = await p.query(
    `SELECT ps.id AS subscription_id, ps.account_id, ps.cancelled_at, ps.plan_type
       FROM pro_subscriptions ps
      WHERE ps.status = 'cancelled'
        AND ps.is_founder = FALSE
        AND ps.plan_type = 'monthly'
        AND ps.cancelled_at IS NOT NULL
        AND ps.cancelled_at < NOW() - ($1 || ' days')::interval
        AND ps.cancelled_at >= NOW() - (($1 + 1) || ' days')::interval
        AND NOT EXISTS (
          SELECT 1 FROM pro_winback_dms w
           WHERE w.account_id = ps.account_id
             AND w.subscription_id = ps.id
             AND w.stage = $2
        )
        AND NOT EXISTS (
          SELECT 1 FROM pro_subscriptions ps2
           WHERE ps2.account_id = ps.account_id
             AND ps2.id != ps.id
             AND ps2.status IN ('active','lifetime','past_due')
        )`,
    [daysAgo, stage]
  );
  return r.rows;
}

async function markWinbackDmSent({ accountId, subscriptionId, stage }) {
  const p = getPool();
  await p.query(
    `INSERT INTO pro_winback_dms (account_id, subscription_id, stage)
     VALUES ($1, $2, $3)
     ON CONFLICT (account_id, subscription_id, stage) DO NOTHING`,
    [accountId, subscriptionId, stage]
  );
}

// Stripe `charge.refunded` handler. Marks any active row with the matching
// payment_intent as refunded. Returns the affected row (if any).
async function markProRefunded(stripePaymentIntent) {
  if (!stripePaymentIntent) return null;
  // Task #318 — widened from `status = 'active'` to cover lifetime
  // (founder) and past_due rows too. Without this, refunding a lifetime
  // purchase (now stored as status='lifetime') would no-op and the
  // founder would keep Pro access despite the refund.
  const p = getPool();
  const r = await p.query(
    `UPDATE pro_subscriptions
        SET status = 'refunded',
            refunded_at = NOW(),
            updated_at = NOW()
      WHERE stripe_payment_intent = $1
        AND status IN ('active','lifetime','past_due')
      RETURNING id, account_id, status, refunded_at`,
    [stripePaymentIntent]
  );
  return r.rows[0] || null;
}

// Admin / debug listing of all active Pro members. Used by the admin panel.
async function listProMembers() {
  // Task #318 — include lifetime and past_due rows so the post-backfill
  // Founders (status='lifetime') still appear, and a single failed
  // payment doesn't yank a player's ProBadge mid-dunning. is_founder is
  // exposed so the frontend can pick the brass Founder badge variant.
  const p = getPool();
  const r = await p.query(
    `SELECT ps.id, ps.account_id, ps.plan_type, ps.amount_cents, ps.currency,
            ps.purchased_at, ps.is_founder,
            COALESCE(rp.display_name, ps.account_id::text) AS display_name
       FROM pro_subscriptions ps
       LEFT JOIN registered_players rp ON rp.account_id = ps.account_id
      WHERE ps.status IN ('active','lifetime','past_due')
      ORDER BY ps.is_founder DESC, ps.purchased_at DESC NULLS LAST, ps.id DESC`
  );
  return r.rows;
}

// =============================================================================
// Task #320 — Commission tiers, coach premium, sponsorships, multi-tenant.
// Commission resolution order (per booking):
//   1. coach.commission_bps (admin override on the coach row)  — wins if NOT NULL
//   2. coach.is_premium → 7% (700 bps) discount for paying premium coaches
//   3. site_settings 'coaching_commission_bps' (seeded 2500 = 25%, the
//      published Rookie rate; admin-editable via the commission panel)
// `bps` (basis points) avoids floating-point drift on the platform fee maths.
// =============================================================================
const COACH_PREMIUM_COMMISSION_BPS = 700;
const DEFAULT_COACHING_COMMISSION_BPS = 1000;

async function getCoachingCommissionBps() {
  const v = await getSetting('coaching_commission_bps');
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n >= 0 && n <= 5000 ? n : DEFAULT_COACHING_COMMISSION_BPS;
}

async function setCoachingCommissionBps(bps) {
  const n = parseInt(bps, 10);
  if (!Number.isFinite(n) || n < 0 || n > 5000) {
    throw new Error('commission_bps must be 0..5000 (0%..50%)');
  }
  await setSetting('coaching_commission_bps', String(n));
  return n;
}

// Resolves the effective commission for the given coach row (NOT account_id, the row
// already in memory — saves a round-trip during booking creation).
// ── Coach tier system (Task #320) ─────────────────────────────────────
// Three auto-assigned commission tiers, recomputed on each booking-completed
// event by evaluateAndAutoTierCoach(). Manual override (commission_override_bps)
// always wins, then Premium subscription, then tier-derived rate.
//
// Promotion rules:
//   Rookie       — default; 0–14 completed sessions OR rating < 4.5
//   Established  — 15+ completed sessions AND avg rating >= 4.5
//   Elite        — 50+ completed sessions AND avg rating >= 4.8
// Tier rates: only "promotion" tiers (established/elite) carry discounted
// fixed rates; rookies use the admin-configurable site default. This keeps
// the global commission slider materially active for the largest cohort of
// coaches and lets earned tiers act as explicit promotional discounts.
const COACH_TIER_RATES_BPS = { established: 1800, elite: 1200 };
function bpsForTier(tier) {
  return COACH_TIER_RATES_BPS[String(tier || '').toLowerCase()] ?? null;
}

async function resolveCommissionBpsForCoach(coachRow) {
  if (!coachRow) return await getCoachingCommissionBps();
  // 1. Manual admin override always wins.
  if (coachRow.commission_override_bps != null) return Number(coachRow.commission_override_bps);
  // 2. Premium subscription (flat 7%).
  if (coachRow.is_premium) return COACH_PREMIUM_COMMISSION_BPS;
  // 3. Promotion-tier discount (established/elite only). Rookies fall through.
  const tierRate = bpsForTier(coachRow.commission_tier);
  if (tierRate != null) return tierRate;
  // 4. Site default (the admin-set global rate — applies to rookies and
  //    coaches with no tier assigned yet).
  return await getCoachingCommissionBps();
}

// Re-compute and persist the auto tier for one coach based on the latest
// completed_sessions + avg rating. Returns the new tier. Safe to call after
// every booking 'completed' transition or rating insert.
async function evaluateAndAutoTierCoach(accountId) {
  const p = getPool();
  const r = await p.query(
    `SELECT
        (SELECT COUNT(*)::int FROM coaching_bookings
           WHERE coach_account_id = $1 AND status = 'completed') AS completed,
        (SELECT ROUND(AVG(rating)::numeric, 2) FROM coaching_reviews
           WHERE coach_account_id = $1) AS avg_rating`,
    [accountId]
  );
  const completed = r.rows[0]?.completed || 0;
  const rating = parseFloat(r.rows[0]?.avg_rating) || 0;
  let tier = 'rookie';
  if (completed >= 50 && rating >= 4.8) tier = 'elite';
  else if (completed >= 15 && rating >= 4.5) tier = 'established';
  await p.query(
    `UPDATE coaches SET commission_tier = $2,
            commission_bps = $3, updated_at = NOW()
       WHERE account_id = $1`,
    [accountId, tier, bpsForTier(tier)]
  );
  return { tier, bps: bpsForTier(tier), completed, avg_rating: rating };
}

async function setCoachCommissionOverride(accountId, { bps, tier } = {}) {
  const p = getPool();
  // bps === null → clear override (revert to auto-tier rate).
  const r = await p.query(
    `UPDATE coaches SET commission_override_bps = $2,
            commission_tier = COALESCE($3, commission_tier),
            updated_at = NOW()
       WHERE account_id = $1
       RETURNING *`,
    [accountId, bps, tier]
  );
  return r.rows[0] || null;
}

async function getCoachPremium(coachAccountId) {
  const p = getPool();
  const r = await p.query(
    `SELECT * FROM coach_premium_subscriptions WHERE coach_account_id = $1`,
    [coachAccountId]
  );
  return r.rows[0] || null;
}

async function upsertCoachPremiumPending({ coachAccountId, stripeCustomerId, priceCents = 999, currency = 'aud' }) {
  const p = getPool();
  const r = await p.query(
    `INSERT INTO coach_premium_subscriptions
       (coach_account_id, status, stripe_customer_id, price_cents, currency)
     VALUES ($1, 'pending', $2, $3, $4)
     ON CONFLICT (coach_account_id) DO UPDATE
       SET stripe_customer_id = COALESCE(EXCLUDED.stripe_customer_id, coach_premium_subscriptions.stripe_customer_id),
           updated_at = NOW()
     RETURNING *`,
    [coachAccountId, stripeCustomerId || null, priceCents, currency]
  );
  return r.rows[0];
}

// Apply a Stripe subscription event payload. Mirrors `is_premium` + `premium_until`
// onto the coach row so reads (browsing /coaches) don't need a join.
async function applyCoachPremiumStripeEvent(coachAccountId, sub) {
  if (!coachAccountId || !sub) return null;
  const p = getPool();
  const status = sub.status === 'trialing' ? 'active' : (sub.status || 'pending');
  const cpe = sub.current_period_end ? new Date(sub.current_period_end * 1000) : null;
  const cancelAtPeriodEnd = !!sub.cancel_at_period_end;
  const cancelledAt = sub.canceled_at ? new Date(sub.canceled_at * 1000) : null;
  const r = await p.query(
    `UPDATE coach_premium_subscriptions
        SET status = $2, stripe_subscription_id = COALESCE(stripe_subscription_id, $3),
            current_period_end = $4, cancel_at_period_end = $5,
            cancelled_at = $6, updated_at = NOW()
      WHERE coach_account_id = $1
      RETURNING *`,
    [coachAccountId, status, sub.id || null, cpe, cancelAtPeriodEnd, cancelledAt]
  );
  const isActive = ['active', 'past_due'].includes(status);
  await p.query(
    `UPDATE coaches SET is_premium = $2, premium_until = $3, updated_at = NOW()
       WHERE account_id = $1`,
    [coachAccountId, isActive, cpe]
  );
  return r.rows[0] || null;
}

// Task #344 — Compute a coach-specific "what Premium would (or did) save you"
// figure plus the aggregate first-week booking lift premium coaches actually
// see. Pulled from existing coaching_bookings + coach_premium_subscriptions
// rows so there is no new tracking surface to populate.
//
// Personal savings: sum the gross amount of the coach's paid/completed
// bookings in the last `days` window, then compute (current_bps − 700) ⨯ gross
// for a non-premium coach ("you would have saved $X"), or (default_bps − 700)
// ⨯ gross for an active premium coach ("you have saved $X vs the standard
// rate"). Returns null monetary fields when there aren't enough bookings to
// be meaningful (the route renders a graceful fallback).
//
// Aggregate first-week lift: compares paid bookings in the first 7 days of
// premium activation against the average non-premium coach's first 7 days
// after coaches.created_at. Returns nulls when sample sizes are too small.
// Task #344 — Record one profile view per (coach, viewer, UTC day). The
// partial unique index makes the throttle a no-op on duplicates so callers
// don't need to pre-check. Failures are swallowed by the caller so a flaky
// write never breaks the public coach detail render.
async function recordCoachProfileView({ coachAccountId, viewerKey, source }) {
  if (!coachAccountId || !viewerKey) return false;
  const p = getPool();
  const r = await p.query(
    `INSERT INTO coach_profile_views (coach_account_id, viewer_key, source)
     VALUES ($1, $2, $3)
     ON CONFLICT (coach_account_id, viewer_key, viewed_on) DO NOTHING
     RETURNING id`,
    [coachAccountId, String(viewerKey).slice(0, 64), source ? String(source).slice(0, 32) : null]
  );
  return r.rowCount > 0;
}

async function getCoachPremiumLift(coachAccountId, { days = 30 } = {}) {
  const p = getPool();
  const coachRow = (await p.query(
    `SELECT * FROM coaches WHERE account_id = $1`, [coachAccountId]
  )).rows[0];
  if (!coachRow) return null;

  const defaultBps = await getCoachingCommissionBps();
  const premiumBps = COACH_PREMIUM_COMMISSION_BPS;
  const currentBps = await resolveCommissionBpsForCoach(coachRow);
  const isPremium = !!coachRow.is_premium;

  const personalQ = await p.query(
    `SELECT COUNT(*)::int AS booking_count,
            COALESCE(SUM(amount_cents), 0)::bigint AS gross_cents
       FROM coaching_bookings
      WHERE coach_account_id = $1
        AND status IN ('paid','completed')
        AND created_at >= NOW() - ($2 || ' days')::interval`,
    [coachAccountId, String(days)]
  );
  const bookingCount = personalQ.rows[0]?.booking_count || 0;
  const grossCents = Number(personalQ.rows[0]?.gross_cents || 0);
  const MIN_BOOKINGS_FOR_PERSONAL = 1;
  const enoughHistory = bookingCount >= MIN_BOOKINGS_FOR_PERSONAL;

  let projectedSavingsCents = null;
  let actualSavingsCents = null;
  if (enoughHistory) {
    if (isPremium) {
      const diff = Math.max(defaultBps - premiumBps, 0);
      actualSavingsCents = Math.round(grossCents * diff / 10000);
    } else {
      const diff = Math.max(currentBps - premiumBps, 0);
      projectedSavingsCents = Math.round(grossCents * diff / 10000);
    }
  }

  const agg = await _computeCoachPremiumFirstWeekViewLift();

  return {
    window_days: days,
    is_premium: isPremium,
    current_bps: currentBps,
    premium_bps: premiumBps,
    default_bps: defaultBps,
    personal: {
      booking_count: bookingCount,
      gross_cents: grossCents,
      enough_history: enoughHistory,
      projected_savings_cents: projectedSavingsCents,
      actual_savings_cents: actualSavingsCents,
    },
    aggregate: agg,
  };
}

// Task #344 — Aggregate first-week *profile-view* lift premium coaches see
// vs non-premium coaches. Pulled from the `coach_profile_views` table this
// task added. Premium cohort is anchored at the first row's created_at in
// `coach_premium_subscriptions` (the row is inserted at checkout, so this
// is close enough to activation in practice). Non-premium cohort is
// anchored at `coaches.created_at`. Both cohorts are restricted to coaches
// whose anchor is at least 7 days in the past so the first-week window is
// fully observable. Returns `sufficient: false` (with nulls everywhere
// except the cohort counts) when either cohort has fewer than 3 coaches —
// the public pitch page hides the line entirely in that case to avoid
// publishing a noisy or misleading number.
async function _computeCoachPremiumFirstWeekViewLift() {
  const p = getPool();
  const aggQ = await p.query(`
    WITH premium_anchors AS (
      SELECT c.account_id, MIN(s.created_at) AS anchor
        FROM coaches c
        JOIN coach_premium_subscriptions s ON s.coach_account_id = c.account_id
       WHERE s.status IN ('active','past_due','cancelled','canceled')
       GROUP BY c.account_id
      HAVING MIN(s.created_at) <= NOW() - INTERVAL '7 days'
    ),
    premium_counts AS (
      SELECT pa.account_id,
             (SELECT COUNT(*) FROM coach_profile_views v
               WHERE v.coach_account_id = pa.account_id
                 AND v.viewed_at >= pa.anchor
                 AND v.viewed_at <  pa.anchor + INTERVAL '7 days') AS cnt
        FROM premium_anchors pa
    ),
    non_premium_anchors AS (
      SELECT c.account_id, c.created_at AS anchor
        FROM coaches c
        LEFT JOIN coach_premium_subscriptions s ON s.coach_account_id = c.account_id
       WHERE s.coach_account_id IS NULL
         AND c.created_at <= NOW() - INTERVAL '7 days'
    ),
    non_premium_counts AS (
      SELECT na.account_id,
             (SELECT COUNT(*) FROM coach_profile_views v
               WHERE v.coach_account_id = na.account_id
                 AND v.viewed_at >= na.anchor
                 AND v.viewed_at <  na.anchor + INTERVAL '7 days') AS cnt
        FROM non_premium_anchors na
    )
    SELECT
      (SELECT COUNT(*)::int FROM premium_counts) AS premium_n,
      (SELECT AVG(cnt)::float FROM premium_counts) AS premium_avg,
      (SELECT COUNT(*)::int FROM non_premium_counts) AS non_premium_n,
      (SELECT AVG(cnt)::float FROM non_premium_counts) AS non_premium_avg
  `);
  const agg = aggQ.rows[0] || {};
  // Task #361 — lowered from 3 to 1 so a freshly-launched Premium tier with
  // a single cohort member can still publish a real ratio, with the UI
  // showing a "based on N coaches" disclosure so the buyer can judge how
  // much weight to put on the number. The prior threshold of 3 was meant to
  // avoid noisy headlines, but in practice it left the lift card stuck on
  // an empty placeholder for months. Anything with at least one premium
  // and one non-premium cohort member produces a defensible ratio when
  // paired with the cohort-size disclosure.
  const MIN_COHORT = 1;
  const premiumN = agg.premium_n || 0;
  const nonPremiumN = agg.non_premium_n || 0;
  const sufficient = premiumN >= MIN_COHORT && nonPremiumN >= MIN_COHORT;
  const premiumAvg = agg.premium_avg != null ? Number(agg.premium_avg) : null;
  const nonPremiumAvg = agg.non_premium_avg != null ? Number(agg.non_premium_avg) : null;
  const ratio = (sufficient && nonPremiumAvg > 0 && premiumAvg != null)
    ? premiumAvg / nonPremiumAvg : null;
  return {
    premium_cohort_n: premiumN,
    non_premium_cohort_n: nonPremiumN,
    premium_first_week_avg_views: premiumAvg,
    non_premium_first_week_avg_views: nonPremiumAvg,
    ratio,
    sufficient,
  };
}

