// Current + best daily win streak for a player on a game. A streak counts
// consecutive solved (won) days up to and including the most recent solved day;
// any unsolved/missing day before `todayStr` breaks it.
async function getGameStreak(accountId, game) {
  const p = getPool();
  const r = await p.query(
    `SELECT puzzle_date::text AS d, won FROM game_results
       WHERE account_id = $1 AND game = $2 AND mode = 'daily'
       ORDER BY puzzle_date DESC`,
    [accountId, game]
  );
  let current = 0;
  let best = 0;
  let run = 0;
  let prev = null;
  // Walk ascending for best-run computation.
  const rowsAsc = r.rows.slice().reverse();
  for (const row of rowsAsc) {
    if (row.won) { run += 1; best = Math.max(best, run); }
    else { run = 0; }
    prev = row;
  }
  // Current streak: count consecutive won days from the newest backwards,
  // requiring each step to be exactly one calendar day apart.
  let expect = null;
  for (const row of r.rows) {
    if (!row.won) break;
    const d = row.d;
    if (expect && d !== expect) break;
    current += 1;
    const dt = new Date(`${d}T00:00:00Z`);
    dt.setUTCDate(dt.getUTCDate() - 1);
    expect = dt.toISOString().slice(0, 10);
  }
  return { current, best };
}

// Today's leaderboard (fewest guesses, then earliest solve) + all-time average
// guesses per player for a game.
async function getGameLeaderboard(game, dateStr, limit = 25) {
  const p = getPool();
  const today = await p.query(
    `SELECT gr.account_id::text AS account_id, gr.guesses, gr.won, gr.created_at,
            COALESCE(n.nickname, ps.persona_name) AS name
       FROM game_results gr
       LEFT JOIN nicknames n ON n.account_id::text = gr.account_id::text
       LEFT JOIN LATERAL (
         SELECT persona_name FROM player_stats
          WHERE account_id::text = gr.account_id::text ORDER BY id DESC LIMIT 1
       ) ps ON TRUE
      WHERE gr.game = $1 AND gr.mode = 'daily' AND gr.puzzle_date = $2 AND gr.won = true
      ORDER BY gr.guesses ASC, gr.created_at ASC
      LIMIT $3`,
    [game, dateStr, Math.max(1, Math.min(100, limit))]
  );
  const allTime = await p.query(
    `SELECT gr.account_id::text AS account_id,
            COUNT(*) FILTER (WHERE gr.won)::int AS solved,
            ROUND(AVG(gr.guesses) FILTER (WHERE gr.won), 2)::float AS avg_guesses,
            COALESCE(n.nickname, ps.persona_name) AS name
       FROM game_results gr
       LEFT JOIN nicknames n ON n.account_id::text = gr.account_id::text
       LEFT JOIN LATERAL (
         SELECT persona_name FROM player_stats
          WHERE account_id::text = gr.account_id::text ORDER BY id DESC LIMIT 1
       ) ps ON TRUE
      WHERE gr.game = $1 AND gr.mode = 'daily'
      GROUP BY gr.account_id, n.nickname, ps.persona_name
      HAVING COUNT(*) FILTER (WHERE gr.won) > 0
      ORDER BY solved DESC, avg_guesses ASC
      LIMIT $2`,
    [game, Math.max(1, Math.min(100, limit))]
  );
  return { today: today.rows, allTime: allTime.rows };
}

// ── Task #848 — first-party analytics ───────────────────────────────────────
// Batch insert of ingested page/tool events. `rows` are pre-validated by the
// route handler: { eventType, route, name, isAuthed, visitorHash }.
async function insertPageEvents(rows) {
  if (!Array.isArray(rows) || !rows.length) return 0;
  const p = getPool();
  const values = [];
  const params = [];
  let i = 1;
  for (const r of rows) {
    values.push(`($${i++}, $${i++}, $${i++}, $${i++}, $${i++})`);
    params.push(r.eventType, r.route, r.name || null, !!r.isAuthed, r.visitorHash || null);
  }
  const res = await p.query(
    `INSERT INTO page_events (event_type, route, name, is_authed, visitor_hash)
     VALUES ${values.join(', ')}`,
    params
  );
  return res.rowCount || 0;
}

// Retention sweep — deletes events older than `days`. Returns rows deleted.
async function prunePageEvents(days = 180) {
  const p = getPool();
  const r = await p.query(
    `DELETE FROM page_events WHERE created_at < NOW() - ($1::int * INTERVAL '1 day')`,
    [Math.max(1, parseInt(days, 10) || 180)]
  );
  return r.rowCount || 0;
}

// Aggregated site-usage stats for the admin Analytics tab. All queries share
// one time-range filter (last N days).
async function getAnalyticsSiteStats(days = 30) {
  const p = getPool();
  const d = Math.max(1, Math.min(365, parseInt(days, 10) || 30));
  const range = `created_at > NOW() - ($1::int * INTERVAL '1 day')`;
  const [summary, daily, topPages, topTools] = await Promise.all([
    p.query(
      `SELECT COUNT(*)::int AS total_views,
              COUNT(DISTINCT visitor_hash)::int AS unique_visitors,
              COUNT(*) FILTER (WHERE is_authed)::int AS authed_views,
              COUNT(*) FILTER (WHERE NOT is_authed)::int AS anon_views
         FROM page_events
        WHERE event_type = 'pageview' AND ${range}`,
      [d]
    ),
    p.query(
      `SELECT created_at::date::text AS day,
              COUNT(*)::int AS views,
              COUNT(DISTINCT visitor_hash)::int AS uniques,
              COUNT(*) FILTER (WHERE is_authed)::int AS authed_views
         FROM page_events
        WHERE event_type = 'pageview' AND ${range}
        GROUP BY 1 ORDER BY 1`,
      [d]
    ),
    p.query(
      `SELECT route,
              COUNT(*)::int AS views,
              COUNT(DISTINCT visitor_hash)::int AS uniques
         FROM page_events
        WHERE event_type = 'pageview' AND ${range}
        GROUP BY route ORDER BY views DESC LIMIT 20`,
      [d]
    ),
    p.query(
      `SELECT COALESCE(name, route) AS tool,
              COUNT(*)::int AS uses,
              COUNT(DISTINCT visitor_hash)::int AS uniques
         FROM page_events
        WHERE event_type = 'tool' AND ${range}
        GROUP BY 1 ORDER BY uses DESC LIMIT 20`,
      [d]
    ),
  ]);
  return {
    days: d,
    summary: summary.rows[0],
    daily: daily.rows,
    topPages: topPages.rows,
    topTools: topTools.rows,
  };
}

// Aggregated mini-game stats from the existing game_results history.
async function getAnalyticsGameStats(days = 30) {
  const p = getPool();
  const d = Math.max(1, Math.min(365, parseInt(days, 10) || 30));
  const range = `created_at > NOW() - ($1::int * INTERVAL '1 day')`;
  const [perGame, daily, summary] = await Promise.all([
    p.query(
      `SELECT game,
              COUNT(*)::int AS plays,
              COUNT(*) FILTER (WHERE mode = 'daily')::int AS daily_plays,
              COUNT(*) FILTER (WHERE mode <> 'daily')::int AS endless_plays,
              COUNT(*) FILTER (WHERE won)::int AS wins,
              COUNT(DISTINCT account_id)::int AS unique_players,
              ROUND(AVG(guesses)::numeric, 2)::float AS avg_guesses
         FROM game_results
        WHERE ${range}
        GROUP BY game ORDER BY plays DESC`,
      [d]
    ),
    p.query(
      `SELECT created_at::date::text AS day,
              COUNT(*)::int AS plays,
              COUNT(*) FILTER (WHERE mode = 'daily')::int AS daily_plays,
              COUNT(DISTINCT account_id)::int AS unique_players
         FROM game_results
        WHERE ${range}
        GROUP BY 1 ORDER BY 1`,
      [d]
    ),
    p.query(
      `SELECT COUNT(*)::int AS total_plays,
              COUNT(DISTINCT account_id)::int AS unique_players,
              COUNT(*) FILTER (WHERE won)::int AS wins,
              COUNT(*) FILTER (WHERE mode = 'daily')::int AS daily_plays
         FROM game_results
        WHERE ${range}`,
      [d]
    ),
  ]);
  return { days: d, summary: summary.rows[0], perGame: perGame.rows, daily: daily.rows };
}

// Candidate scoreboard rows for the Statline mini-game. Pulls real inhouse
// player_stats lines (account-linked, non-trivial games) joined to match
// duration + win. The caller deterministically picks one per day.
async function getStatlineCandidates(limit = 400) {
  const p = getPool();
  const r = await p.query(
    `SELECT ps.hero_id, ps.kills, ps.deaths, ps.assists, ps.gpm, ps.xpm,
            ps.last_hits, ps.denies, ps.net_worth, ps.level,
            ps.hero_damage, ps.tower_damage, ps.hero_healing,
            m.duration,
            (CASE WHEN ps.team = 'radiant' THEN m.radiant_win ELSE NOT m.radiant_win END) AS win
       FROM player_stats ps
       JOIN matches m ON m.match_id = ps.match_id
      WHERE ps.hero_id > 0
        AND m.duration > 600
        AND (ps.kills + ps.assists) > 0
        AND ps.gpm > 0
      ORDER BY m.date DESC
      LIMIT $1`,
    [Math.max(1, Math.min(2000, limit))]
  );
  return r.rows;
}

// ── Task #666 — Mystery Player mini-game ────────────────────────────────────
// The inverse of Statline: the hero/items/stats are revealed and the hidden
// answer is the inhouse *player*. Pulls real account-linked scoreboard lines
// (same "informative line" filters as Statline) and carries the player's
// resolved display name + the match_id/slot so the caller can attach the item
// build. Anonymised accounts are excluded from the answer pool by joining
// player_profiles and requiring anonymized_at IS NULL.
async function getPlayerStatlineCandidates(limit = 400) {
  const p = getPool();
  const r = await p.query(
    `SELECT ps.account_id::text AS account_id,
            COALESCE(n.nickname, ps.persona_name) AS player_name,
            ps.match_id, ps.slot,
            ps.hero_id, ps.kills, ps.deaths, ps.assists, ps.gpm, ps.xpm,
            ps.last_hits, ps.denies, ps.net_worth, ps.level,
            ps.hero_damage, ps.tower_damage, ps.hero_healing,
            m.duration,
            (CASE WHEN ps.team = 'radiant' THEN m.radiant_win ELSE NOT m.radiant_win END) AS win
       FROM player_stats ps
       JOIN matches m ON m.match_id = ps.match_id
       LEFT JOIN nicknames n ON n.account_id = ps.account_id
       LEFT JOIN player_profiles pp ON pp.account_id = ps.account_id
      WHERE ps.hero_id > 0
        AND ps.account_id > 0
        AND m.duration > 600
        AND (ps.kills + ps.assists) > 0
        AND ps.gpm > 0
        AND pp.anonymized_at IS NULL
        AND COALESCE(n.nickname, ps.persona_name) <> ''
      ORDER BY m.date DESC
      LIMIT $1`,
    [Math.max(1, Math.min(2000, limit))]
  );
  return r.rows;
}

// The 6 main-inventory items (item_slot 0..5) for one scoreboard line, in slot
// order, dropping empty slots. Used to attach the revealed item build to a
// Mystery Player puzzle clue.
async function getLineItems(matchId, slot) {
  const p = getPool();
  const r = await p.query(
    `SELECT item_id, item_name FROM player_items
       WHERE match_id = $1 AND slot = $2 AND item_slot BETWEEN 0 AND 5
       ORDER BY item_slot ASC`,
    [String(matchId), slot]
  );
  return r.rows.filter(it => it.item_name && it.item_name !== 'item_empty');
}

// Roster of inhouse players (account id + resolved display name) for the
// Mystery Player guess autocomplete. Excludes unlinked (account_id = 0) and
// anonymised accounts, de-dupes to one row per account (newest persona), and
// returns numeric ids sorted by display name.
async function getInhousePlayerRoster() {
  const p = getPool();
  const r = await p.query(
    `SELECT DISTINCT ON (ps.account_id)
            ps.account_id::text AS id,
            COALESCE(n.nickname, ps.persona_name) AS name
       FROM player_stats ps
       LEFT JOIN nicknames n ON n.account_id = ps.account_id
       LEFT JOIN player_profiles pp ON pp.account_id = ps.account_id
      WHERE ps.account_id > 0
        AND pp.anonymized_at IS NULL
        AND COALESCE(n.nickname, ps.persona_name) <> ''
      ORDER BY ps.account_id, ps.id DESC`
  );
  return r.rows
    .map(x => ({ id: Number(x.id), name: x.name }))
    .filter(x => Number.isFinite(x.id) && x.name)
    .sort((a, b) => a.name.localeCompare(b.name));
}

// Per-player summary across all games for the hub + profile widget.
async function getGameStats(accountId) {
  const p = getPool();
  const r = await p.query(
    `SELECT game,
            COUNT(*) FILTER (WHERE mode = 'daily')::int AS daily_played,
            COUNT(*) FILTER (WHERE mode = 'daily' AND won)::int AS daily_won,
            ROUND(AVG(guesses) FILTER (WHERE mode = 'daily' AND won), 2)::float AS avg_guesses
       FROM game_results
      WHERE account_id = $1
      GROUP BY game`,
    [accountId]
  );
  return r.rows;
}

// Task #459 — Mobile "Inbox" aggregate. Returns every item currently awaiting
// the signed-in account's response, grouped by kind, so the mobile inbox can
// render in a single fetch. Each kind is queried independently and guarded so
// a partial failure (e.g. a missing optional table) degrades to an empty list
// for that kind rather than blanking the whole inbox. Row shapes intentionally
// carry just enough context for a list row + the deep-link id; the action
// screens fetch their own detail.
async function getPendingActionsForAccount(accountId) {
  const p = getPool();
  const acct = String(accountId);

  // 1. Ready-checks — sessions in the timed accept phase where this account is
  //    a registered player that hasn't accepted yet.
  const readyChecks = (async () => {
    const r = await p.query(
      `SELECT s.id AS session_id, s.notes, s.captain_mode,
              s.accept_phase_starts_at, s.accept_phase_seconds
         FROM inhouse_session_players isp
         JOIN inhouse_sessions s ON s.id = isp.session_id
        WHERE isp.account_id = $1
          AND s.status = 'accepting'
          AND COALESCE(s.is_diagnostic, false) = false
          AND isp.status = 'registered'
          AND isp.accepted_at IS NULL
        ORDER BY s.accept_phase_starts_at DESC NULLS LAST`,
      [acct]
    );
    return r.rows.map(row => ({
      kind: 'ready-check',
      id: String(row.session_id),
      title: 'Lobby ready check',
      subtitle: row.notes ? String(row.notes).slice(0, 120) : 'Confirm you\'re ready to play.',
      accept_phase_starts_at: row.accept_phase_starts_at,
      accept_phase_seconds: row.accept_phase_seconds,
    }));
  })();

  // 2. Scrim proposals — pending scrims where this account captains/owns the
  //    opponent team that has to respond.
  const scrims = (async () => {
    const r = await p.query(
      `SELECT ts.id, ts.scheduled_at, ts.note,
              pt.name AS proposer_name, pt.tag AS proposer_tag
         FROM team_scrims ts
         JOIN team_members tm
           ON tm.team_id = ts.opponent_team_id
          AND tm.account_id = $1
          AND tm.role IN ('owner','captain')
         JOIN teams pt ON pt.id = ts.proposer_team_id
        WHERE ts.status = 'pending'
        ORDER BY ts.scheduled_at ASC NULLS LAST`,
      [acct]
    );
    return r.rows.map(row => ({
      kind: 'scrim',
      id: String(row.id),
      title: 'Scrim proposal',
      subtitle: `${row.proposer_name || 'A team'}${row.proposer_tag ? ` [${row.proposer_tag}]` : ''} wants to scrim.`,
      scheduled_at: row.scheduled_at,
    }));
  })();

  // 3. Roster transfers awaiting this captain's approval (reuses the existing
  //    two-captain confirm query).
  const transfers = (async () => {
    const rows = await getPendingTransfersForCaptain(acct);
    return rows.map(row => ({
      kind: 'roster-transfer',
      id: String(row.id),
      title: 'Roster transfer',
      subtitle: `${row.nickname || 'A player'}: ${row.from_team_name || 'Free agent'} → ${row.to_team_name || 'team'}`,
    }));
  })();

  // 4. MVP-vote windows still open — matches this account played in the last
  //    24h where they haven't yet cast an MVP vote.
  const mvpVotes = (async () => {
    const r = await p.query(
      `SELECT m.match_id, m.date
         FROM player_stats ps
         JOIN matches m ON m.match_id = ps.match_id
        WHERE ps.account_id = $1
          AND ps.account_id <> 0
          AND m.date > NOW() - INTERVAL '24 hours'
          AND NOT EXISTS (
            SELECT 1 FROM match_ratings mr
             WHERE mr.match_id = m.match_id
               AND mr.rater_account_id = $1
               AND mr.is_mvp_vote = TRUE
          )
        ORDER BY m.date DESC`,
      [acct]
    );
    return r.rows.map(row => ({
      kind: 'mvp-vote',
      id: String(row.match_id),
      title: 'Vote for MVP',
      subtitle: `Pick the standout from match ${row.match_id}.`,
      match_date: row.date,
    }));
  })();

  // 5. Coaching booking reminders — sent but not yet acknowledged, still upcoming.
  const bookingReminders = (async () => {
    const r = await p.query(
      `SELECT cb.id, cb.slot_start_at, cb.duration_minutes,
              cb.coach_account_id, n.nickname AS coach_name
         FROM coaching_bookings cb
         LEFT JOIN nicknames n ON n.account_id = cb.coach_account_id
        WHERE cb.student_account_id = $1
          AND cb.status = 'paid'
          AND cb.reminder_sent_at IS NOT NULL
          AND cb.reminder_acked_at IS NULL
        ORDER BY cb.slot_start_at ASC`,
      [acct]
    );
    return r.rows.map(row => ({
      kind: 'booking-reminder',
      id: String(row.id),
      title: 'Coaching session soon',
      subtitle: `Session with ${row.coach_name || 'your coach'} is coming up.`,
      slot_start_at: row.slot_start_at,
    }));
  })();

  const results = await Promise.all([
    readyChecks.catch((e) => { console.warn('[pending-actions] ready-checks failed:', e.message); return []; }),
    scrims.catch((e) => { console.warn('[pending-actions] scrims failed:', e.message); return []; }),
    transfers.catch((e) => { console.warn('[pending-actions] transfers failed:', e.message); return []; }),
    mvpVotes.catch((e) => { console.warn('[pending-actions] mvp-votes failed:', e.message); return []; }),
    bookingReminders.catch((e) => { console.warn('[pending-actions] booking-reminders failed:', e.message); return []; }),
  ]);

  const actions = results.flat();
  return { actions, count: actions.length };
}

// ── Steam-account-linked staff roles (admin / moderator) ──────────────────
// The OWNER (superuser) is resolved separately via SUPERUSER_PASSWORD and is
// never stored here; this table only holds the two lower tiers.
async function getAdminRole(accountId) {
  if (!accountId) return null;
  const p = getPool();
  const { rows } = await p.query(
    'SELECT role FROM admin_roles WHERE account_id = $1',
    [String(accountId)]
  );
  return rows.length ? rows[0].role : null;
}

async function listAdminRoles() {
  const p = getPool();
  const { rows } = await p.query(`
    SELECT ar.account_id::text AS account_id,
           ar.role,
           ar.granted_by::text AS granted_by,
           ar.granted_at,
           ar.updated_at,
           n.nickname AS display_name,
           pl.discord_id
      FROM admin_roles ar
      LEFT JOIN nicknames n ON n.account_id = ar.account_id
      LEFT JOIN players  pl ON pl.account_id_32 = ar.account_id::text
     ORDER BY ar.role ASC, ar.granted_at ASC
  `);
  return rows;
}

async function setAdminRole(accountId, role, grantedBy) {
  if (!accountId) throw new Error('accountId required');
  if (role !== 'admin' && role !== 'moderator') throw new Error('invalid role');
  const p = getPool();
  const { rows } = await p.query(`
    INSERT INTO admin_roles (account_id, role, granted_by, granted_at, updated_at)
    VALUES ($1, $2, $3, NOW(), NOW())
    ON CONFLICT (account_id) DO UPDATE
      SET role = EXCLUDED.role,
          granted_by = EXCLUDED.granted_by,
          updated_at = NOW()
    RETURNING account_id::text AS account_id, role, granted_by::text AS granted_by, granted_at, updated_at
  `, [String(accountId), role, grantedBy ? String(grantedBy) : null]);
  return rows[0];
}

async function removeAdminRole(accountId) {
  if (!accountId) return false;
  const p = getPool();
  const { rowCount } = await p.query(
    'DELETE FROM admin_roles WHERE account_id = $1',
    [String(accountId)]
  );
  return rowCount > 0;
}

