// 1.4 — Per-match stats timeseries for the player's own profile chart v2.
// Returns up to 100 most-recent matches with K/D/A, GPM, hero damage and a
// rolling K/D/A tracked client-side. Cheap query — single index lookup on
// player_stats.account_id then a join.
async function getPlayerMatchStatsHistory(accountId, seasonId = null) {
  const p = getPool();
  const params = [accountId];
  const sc = seasonId ? ` AND m.season_id = $${params.push(parseInt(seasonId))}` : ' AND m.is_legacy = false';
  const result = await p.query(`
    SELECT
      m.match_id,
      m.date,
      ps.kills,
      ps.deaths,
      ps.assists,
      ps.gpm,
      ps.xpm,
      ps.hero_damage,
      ps.hero_id,
      CASE WHEN (ps.team = 'radiant' AND m.radiant_win) OR (ps.team = 'dire' AND NOT m.radiant_win)
        THEN 1 ELSE 0
      END AS won
    FROM player_stats ps
    JOIN matches m ON m.match_id::text = ps.match_id::text
    WHERE ps.account_id::text = $1::text${sc}
    ORDER BY m.date DESC
    LIMIT 100
  `, params);
  // Reverse so caller gets oldest -> newest for charting.
  return result.rows.reverse();
}

// Task #444 — Pre-match mood & form widget.
// Pulls the player's most recent ~60 non-legacy matches (date, hero_id, won)
// in a single query and derives:
//   * last7 / last14 W-L records
//   * weekday win-rate breakdown (Australia/Sydney) with a "best weekday"
//     pick over the trailing window
//   * hot-hero detection over the last 10 matches (≥3 games, ≥60% WR)
// All math happens in JS so the SQL stays as a single index lookup. Returns
// `null`-shaped fields when the player has no recent matches so the widget
// can render a friendly empty state instead of breaking.
async function getPlayerFormSummary(accountId) {
  const p = getPool();
  const r = await p.query(`
    SELECT m.date, ps.hero_id,
      CASE WHEN (ps.team = 'radiant' AND m.radiant_win)
             OR (ps.team = 'dire' AND NOT m.radiant_win)
        THEN 1 ELSE 0 END AS won
    FROM player_stats ps
    JOIN matches m ON m.match_id::text = ps.match_id::text
    WHERE ps.account_id::text = $1::text AND m.is_legacy = false
    ORDER BY m.date DESC
    LIMIT 60
  `, [String(accountId)]);
  const rows = r.rows || [];
  const total = rows.length;
  if (total === 0) {
    return {
      total, sample: 0,
      last7: { wins: 0, losses: 0, games: 0 },
      last14: { wins: 0, losses: 0, games: 0 },
      weekday: null,
      hotHero: null,
    };
  }
  const now = Date.now();
  const D = 24 * 60 * 60 * 1000;
  const tally = (since) => {
    let w = 0, l = 0;
    for (const row of rows) {
      const t = new Date(row.date).getTime();
      if (now - t > since) continue;
      if (row.won) w++; else l++;
    }
    return { wins: w, losses: l, games: w + l };
  };
  const last7 = tally(7 * D);
  const last14 = tally(14 * D);

  // Weekday breakdown in Australia/Sydney — that's the bot's canonical TZ.
  // `Intl.DateTimeFormat` with `weekday: 'long'` is the most robust way to
  // pull a TZ-correct day name in Node without bringing in a date lib.
  const weekdayFmt = new Intl.DateTimeFormat('en-AU', {
    weekday: 'long', timeZone: 'Australia/Sydney',
  });
  const byDay = {};
  for (const row of rows) {
    const day = weekdayFmt.format(new Date(row.date));
    if (!byDay[day]) byDay[day] = { wins: 0, losses: 0, games: 0 };
    if (row.won) byDay[day].wins++; else byDay[day].losses++;
    byDay[day].games++;
  }
  const overallWr = rows.reduce((s, r) => s + (r.won ? 1 : 0), 0) / total;
  let bestDay = null;
  for (const [day, t] of Object.entries(byDay)) {
    if (t.games < 3) continue; // need a minimum sample before bragging
    const wr = t.wins / t.games;
    const lift = wr - overallWr;
    if (!bestDay || lift > bestDay.lift) bestDay = { day, wr, lift, ...t };
  }

  // Hot hero — over the most recent 10 matches, find any hero with ≥3 games
  // played and ≥60% win rate. If multiple qualify, pick the one with the
  // highest WR (then highest games as a tiebreak).
  const recent10 = rows.slice(0, 10);
  const byHero = {};
  for (const row of recent10) {
    if (!row.hero_id) continue;
    const k = String(row.hero_id);
    if (!byHero[k]) byHero[k] = { hero_id: row.hero_id, wins: 0, games: 0 };
    if (row.won) byHero[k].wins++;
    byHero[k].games++;
  }
  let hotHero = null;
  for (const h of Object.values(byHero)) {
    if (h.games < 3) continue;
    const wr = h.wins / h.games;
    if (wr < 0.6) continue;
    if (!hotHero || wr > hotHero.wr || (wr === hotHero.wr && h.games > hotHero.games)) {
      hotHero = { hero_id: h.hero_id, wins: h.wins, games: h.games, wr };
    }
  }

  return { total, sample: total, last7, last14, weekday: bestDay, hotHero };
}

async function getHallOfFameCareerStats(seasonId = null) {
  const p = getPool();
  const params = [];
  const sc = seasonId ? ` AND m.season_id = $${params.push(parseInt(seasonId))}` : ' AND m.is_legacy = false';
  const result = await p.query(`
    SELECT
      ps.account_id,
      COALESCE(n.nickname, ps.persona_name) AS display_name,
      COUNT(DISTINCT ps.match_id) AS games,
      SUM(CASE WHEN (ps.team = 'radiant' AND m.radiant_win) OR (ps.team = 'dire' AND NOT m.radiant_win) THEN 1 ELSE 0 END) AS wins,
      SUM(CASE WHEN (ps.team = 'radiant' AND NOT m.radiant_win) OR (ps.team = 'dire' AND m.radiant_win) THEN 1 ELSE 0 END) AS losses,
      ROUND(AVG(CASE WHEN ps.deaths > 0 THEN (ps.kills + ps.assists)::float / ps.deaths ELSE (ps.kills + ps.assists)::float END)::numeric, 2) AS avg_kda,
      ROUND(AVG(ps.gpm)::numeric) AS avg_gpm,
      SUM(ps.kills) AS total_kills,
      (SELECT COUNT(*) FROM achievements a WHERE a.player_id = ps.account_id) AS achievement_count
    FROM player_stats ps
    JOIN matches m ON m.match_id::text = ps.match_id::text
    LEFT JOIN nicknames n ON n.account_id::text = ps.account_id::text
    WHERE ps.account_id::text != '0'${sc}
    GROUP BY ps.account_id, COALESCE(n.nickname, ps.persona_name)
    HAVING COUNT(DISTINCT ps.match_id) >= 1
    ORDER BY wins DESC, games DESC
  `, params);
  return result.rows;
}

async function getPlayerBenchmarkAverages(seasonId = null) {
  const p = getPool();
  const params = [];
  const seasonClause = seasonId
    ? ` AND ps.match_id IN (SELECT match_id FROM matches WHERE season_id = $${params.push(parseInt(seasonId))})`
    : '';
  const result = await p.query(`
    SELECT
      CASE WHEN ps.account_id != 0 THEN ps.account_id::text ELSE ps.persona_name END AS account_id,
      COALESCE(MAX(n.nickname), MAX(ps.persona_name)) AS display_name,
      COUNT(DISTINCT ps.match_id) AS games,
      ROUND(AVG(ps.kills)::numeric, 2) AS avg_kills,
      ROUND(AVG(ps.deaths)::numeric, 2) AS avg_deaths,
      ROUND(AVG(ps.assists)::numeric, 2) AS avg_assists,
      ROUND(AVG(ps.gpm)::numeric) AS avg_gpm,
      ROUND(AVG(ps.xpm)::numeric) AS avg_xpm,
      ROUND(AVG(ps.hero_damage)::numeric) AS avg_hero_damage,
      ROUND(AVG(ps.tower_damage)::numeric) AS avg_tower_damage,
      ROUND(AVG(ps.hero_healing)::numeric) AS avg_healing,
      ROUND(AVG(ps.last_hits)::numeric) AS avg_last_hits,
      ROUND(AVG(CASE WHEN ps.deaths > 0 THEN (ps.kills + ps.assists)::numeric / ps.deaths ELSE (ps.kills + ps.assists)::numeric END), 2) AS avg_kda
    FROM player_stats ps
    LEFT JOIN nicknames n ON n.account_id::text = ps.account_id::text
    WHERE (ps.account_id != 0 OR (ps.persona_name IS NOT NULL AND ps.persona_name != ''))${seasonClause}
    GROUP BY CASE WHEN ps.account_id != 0 THEN ps.account_id::text ELSE ps.persona_name END
    HAVING COUNT(DISTINCT ps.match_id) >= 1
    ORDER BY games DESC
  `, params);
  return result.rows;
}

async function getTournaments(seasonId = null, { tenantId } = {}) {
  const p = getPool();
  const params = [];
  const conds = [];
  if (seasonId) conds.push(`t.season_id = $${params.push(parseInt(seasonId))}`);
  // Task #333 — tenant scope. tenantId == null filters to default tenant
  // (tenant_id IS NULL); 'all' opts out of any tenant filter (admin-only).
  if (tenantId !== 'all') {
    if (tenantId == null) {
      conds.push(`t.tenant_id IS NULL`);
    } else {
      const id = parseInt(tenantId, 10);
      if (Number.isFinite(id)) conds.push(`t.tenant_id = $${params.push(id)}`);
      else conds.push(`t.tenant_id IS NULL`);
    }
  }
  const where = conds.length ? `WHERE ${conds.join(' AND ')}` : '';
  const result = await p.query(`
    SELECT t.*, s.name AS season_name,
      (SELECT COUNT(*) FROM tournament_participants tp WHERE tp.tournament_id = t.id) AS participant_count
    FROM tournaments t
    LEFT JOIN seasons s ON s.id = t.season_id
    ${where}
    ORDER BY t.created_at DESC
  `, params);
  return result.rows;
}

async function getTournamentById(id) {
  const p = getPool();
  const parsed = parseInt(id);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    console.warn(`[db.getTournamentById] non-numeric id received: ${JSON.stringify(id)}`);
    return null;
  }
  const result = await p.query(`
    SELECT t.*, s.name AS season_name
    FROM tournaments t
    LEFT JOIN seasons s ON s.id = t.season_id
    WHERE t.id = $1
  `, [parsed]);
  if (!result.rows[0]) {
    console.warn(`[db.getTournamentById] no tournament with id=${parsed}`);
  }
  return result.rows[0] || null;
}

async function createTournament({
  name, description, seasonId, format, createdBy,
  tierNumber = null, entryFeeCents = 0,
  signupOpenAt = null, signupCloseAt = null,
  bracketSize = null,
  maxParticipants = null, prizeSplit = null,
  tenantId = null,
  // Task #412 — Tournament v2 additions
  swissRounds = null, checkinOffsetMin = null, tieBreakMethod = null,
  startsAt = null,
}) {
  const p = getPool();
  const fmt = format || 'single_elim';
  // Validate prize split server-side: array of positive numbers that sum to 100.
  let splitJson = null;
  if (prizeSplit != null) {
    if (!Array.isArray(prizeSplit) || prizeSplit.length === 0) {
      throw new Error('prizeSplit must be a non-empty array of percentages');
    }
    const nums = prizeSplit.map(v => Number(v));
    if (nums.some(n => !Number.isFinite(n) || n < 0)) {
      throw new Error('prizeSplit entries must be non-negative numbers');
    }
    const sum = nums.reduce((a, b) => a + b, 0);
    if (Math.round(sum) !== 100) {
      throw new Error(`prizeSplit must sum to 100 (got ${sum})`);
    }
    splitJson = JSON.stringify(nums);
  }
  const result = await p.query(
    `INSERT INTO tournaments (name, description, season_id, format, bracket_type, bracket_size, status, created_by,
       tier_number, entry_fee_cents, signup_open_at, signup_close_at, max_participants, prize_split, tenant_id,
       swiss_rounds, checkin_offset_min, tie_break_method, starts_at)
     VALUES ($1, $2, $3, $4, $5, $6, 'upcoming', $7, $8, $9, $10, $11, $12,
             COALESCE($13::jsonb, '[50,30,20]'::jsonb), $14,
             $15, COALESCE($16, 30), COALESCE($17, 'buchholz'), $18)
     RETURNING *`,
    [
      name,
      description || null,
      seasonId ? parseInt(seasonId) : null,
      fmt,
      fmt === 'weekend_points' ? 'none' : (fmt === 'swiss' ? 'swiss' : fmt),
      bracketSize ? parseInt(bracketSize) : null,
      createdBy || null,
      tierNumber != null ? parseInt(tierNumber) : null,
      parseInt(entryFeeCents) || 0,
      signupOpenAt ? new Date(signupOpenAt) : null,
      signupCloseAt ? new Date(signupCloseAt) : null,
      maxParticipants != null && maxParticipants !== '' ? parseInt(maxParticipants) : null,
      splitJson,
      tenantId != null ? parseInt(tenantId) : null,
      swissRounds != null && swissRounds !== '' ? parseInt(swissRounds) : null,
      checkinOffsetMin != null && checkinOffsetMin !== '' ? parseInt(checkinOffsetMin) : null,
      tieBreakMethod || null,
      startsAt ? new Date(startsAt) : null,
    ]
  );
  const created = result.rows[0];
  // Mirror per-place prize splits into the normalized table so the new
  // /prize-splits endpoint returns them immediately for newly-created events.
  if (created && splitJson) {
    try {
      const nums = JSON.parse(splitJson);
      for (let i = 0; i < nums.length; i++) {
        await p.query(
          `INSERT INTO tournament_prize_splits (tournament_id, place, percent)
           VALUES ($1, $2, $3)
           ON CONFLICT (tournament_id, place) DO UPDATE SET percent = EXCLUDED.percent`,
          [created.id, i + 1, nums[i]]);
      }
    } catch (_) { /* best-effort */ }
  }
  return created;
}

